import { describe, expect, it } from 'vitest';
import { activeCues, parseAss, parseSrtOrVtt, parseSubtitles, settledPart } from './subtitles';

const SRT = `1
00:00:35,118 --> 00:00:36,201
Kom op.

2
00:00:37,454 --> 00:00:38,371
<i>O, ja.</i>
Tweede regel
`;

const VTT = `WEBVTT

00:01.000 --> 00:02.500 align:center
Hello

intro
01:00:00.000 --> 01:00:01.000
<b>Bold</b> text
`;

// Real PMS output for an embedded SRT, converted to ASS by its transcoder.
const PMS_ASS = `[Script Info]
; Script generated by FFmpeg/Lavc60.31.102
ScriptType: v4.00+

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Arial,16,&Hffffff,&Hffffff,&H0,&H0,0,0,0,0,100,100,0,0,1,1,0,2,10,10,10,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:04.58,0:00:05.58,Default,,0,0,0,,{\\i1}I found it.{\\i0}
Dialogue: 0,0:08:00.71,0:08:02.41,Default,,0,0,0,,To that end, I've brought in...\\Nsomeone, finally
Dialogue: 0,0:08:02.45`;

describe('subtitle parsing', () => {
	it('parses SRT with tags stripped and multiple lines', () => {
		expect(parseSrtOrVtt(SRT)).toEqual([
			{ start: 35.118, end: 36.201, text: 'Kom op.' },
			{ start: 37.454, end: 38.371, text: 'O, ja.\nTweede regel' }
		]);
	});

	it('parses WebVTT with cue settings, identifiers and short timestamps', () => {
		expect(parseSrtOrVtt(VTT)).toEqual([
			{ start: 1, end: 2.5, text: 'Hello' },
			{ start: 3600, end: 3601, text: 'Bold text' }
		]);
	});

	it('parses PMS ASS output, including a partial last line, keeping commas in text', () => {
		expect(parseAss(PMS_ASS)).toEqual([
			{ start: 4.58, end: 5.58, text: 'I found it.' },
			{ start: 480.71, end: 482.41, text: "To that end, I've brought in...\nsomeone, finally" }
		]);
	});

	it('detects the format automatically', () => {
		expect(parseSubtitles(PMS_ASS)).toHaveLength(2);
		expect(parseSubtitles(SRT)).toHaveLength(2);
	});

	it('keeps only whole cues of a subtitle that is still arriving', () => {
		// Cut mid-text, as PMS's progressive output and the network can split it.
		const ass = PMS_ASS.replace('Dialogue: 0,0:08:02.45', '').replace('someone, finally\n', 'some');
		expect(parseSubtitles(settledPart(ass))).toEqual([
			{ start: 4.58, end: 5.58, text: 'I found it.' }
		]);
		expect(parseSubtitles(settledPart(PMS_ASS))).toHaveLength(2);

		const srt = SRT.replace('Tweede regel\n', 'Twee');
		expect(parseSubtitles(settledPart(srt))).toEqual([
			{ start: 35.118, end: 36.201, text: 'Kom op.' }
		]);
		expect(settledPart('1\n00:00:35,118 --> 00:00:36,201\nKom')).toBe('');
		expect(parseSubtitles(settledPart(SRT.replace(/\n/g, '\r\n') + '\r\n'))).toHaveLength(2);
	});

	it('finds the cues on screen at a time', () => {
		const cues = parseSrtOrVtt(SRT);
		expect(activeCues(cues, 35.5).map((c) => c.text)).toEqual(['Kom op.']);
		expect(activeCues(cues, 36.5)).toEqual([]);
	});
});
